UPDATE companies SET description='CMC Steel Alabama operates a steel mill in Birmingham, Alabama, as part of Commercial Metals Company (CMC), which emphasizes its heritage and innovative spirit in steelmaking. The facility uses electric arc furnace technology in a mini-mill configuration, with a melt capacity exceeding 5 million tons of finished long steel products annually. It produces a wide range of products including rebar, merchant bar, wire rod, and specialty engineered steels such as ChromX (corrosion-resistant reinforcing steel), GalvaBar (continuously galvanized rebar), CryoSteel (for cryogenic applications down to −274 °F), and Impact Metals (armor-grade steel). The mill also manufactures fence posts from 100% recycled U.S. billet steel and offers value-added processing like spooled and coiled rebar, structural shapes, and specialty bar items.

Its specialty products target marine infrastructure, defense and transportation OEMs, heavy equipment manufacturers, and LNG projects requiring cryogenic performance.

CMC differentiates itself through its low-carbon EAF steelmaking process, which it says produces 63% lower emissions intensity than the industry average, supplemented by renewable energy credits and carbon offsets. Proprietary product lines like ChromX and CryoSteel are designed to extend service life in harsh environments, while an integrated logistics network across multiple states supports reliable supply.', certifications=ARRAY['LEED']::text[], profile='{"capabilities": ["Electric arc furnace steelmaking", "Mini-mill steelmaking", "Micro-mill steelmaking", "Rolling of rebar (including spooled and coiled)", "Rolling of merchant bar (angles, channels, flats, squares, rounds)", "Rolling of wire rod", "Production of ChromX corrosion-resistant reinforcing steel", "Production of GalvaBar continuously galvanized rebar", "Production of CryoSteel cryogenic reinforcing steel", "Production of Impact Metals armor-grade steel", "Production of fence posts from recycled billet steel", "Value-added processing: T-post stock, rub rail, checked leg angle, earth bar, wire rod coil", "Carbon-neutral steel production via EAF with renewable energy credits and offsets"], "industries": ["Construction", "Infrastructure", "Energy", "Commercial building", "Industrial manufacturing", "Marine", "Defense", "Transportation", "Heavy equipment", "Oil and gas (LNG)", "Service centers", "Joist manufacturing", "Metal building fabrication", "Precast concrete"], "materials": ["Steel (carbon and alloy)", "Recycled billet steel", "Chromium-alloyed steel (ChromX)", "Galvanized steel (GalvaBar)", "Cryogenic steel (CryoSteel)", "Armor-grade steel (Impact Metals)"], "equipment": ["Electric arc furnace", "Mini-mill", "Micro-mill"], "volume": "Over 5 million tons per year", "lead_time": "", "tolerances": "", "built_on": ["Melt capacity over 5 million tons of finished long steel products per year", "Electric arc furnace process with 63% lower emissions intensity than industry average", "Proprietary products: ChromX (100-year corrosion resistance), GalvaBar (galvanized rebar), CryoSteel (extreme cold toughness), Impact Metals (armor-grade)", "Integrated multi-state logistics and sales network", "Mini-mill / micro-mill steelmaking technology"], "facts_used": ["name: CMC Steel Alabama -> db", "location: Birmingham, Alabama -> db", "description: heritage, innovative spirit, automation, environmentally friendly process advancements -> db", "certifications: LEED -> db", "capabilities: flexibility, MSCI, mill capability -> db", "products: rebar, merchant bar, wire rod, ChromX, GalvaBar, CryoSteel, Impact Metals, fence posts -> db", "industries_served: reinforcing steel industry -> db", "page content: electric arc furnace technology, melt capacity over 5 million tons, mini-mill process, micro-mill steelmaking, product details, industries, trade associations, carbon neutral steel -> pages[''/'']"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Using advanced electric arc furnace technology and strict quality standards, we produce high-performance steels", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='cmc-steel-alabama' AND approved AND profile IS NULL;
UPDATE companies SET description='CRP Automotive operates as a business unit of CRP Industries, a veteran-owned family business headquartered in Cranbury, New Jersey. Founded in 1954, the company began as a small importer offering roughly 200 sizes of German-manufactured tires to the North American market. Over more than 70 years of continuous operation, it has grown into an industry leader supplying thousands of automotive replacement parts and fluids across the continent. The privately held company spans three generations of family ownership and maintains additional facilities in South Carolina, Michigan, and Puebla, Mexico.

The company develops, manufactures, and distributes a broad portfolio of aftermarket products under brands that include AAE steering components, Rein Automotive parts, Pentosin technical fluids, and AJUSA gaskets and head bolts. Beyond new parts, CRP has extensive capabilities in mechanical and electronic remanufacturing, restoring components such as ABS modules, electronic power-steering modules, transmission control modules, instrument clusters, engine control modules, hybrid system inverters, and a range of other mechatronic units. Its product catalog, accessible via an online platform powered by ShowMeTheParts.com, covers nearly every automotive service and repair category for both import and domestic vehicles.

CRP Automotive serves the professional automotive repair market, working closely with technicians who select and install its products in shops across North America. The company also partners with major e-catalog platforms such as Activant/Epicor and WHI to ensure parts data reaches installers efficiently.

CRP states its purpose is to build a sustainable community where people and machines perform at their best, and its vision is to be the service-market partner that creates solutions for problems caused by advancing vehicle technology. The firm emphasizes its deep remanufacturing expertise and direct engagement with repair professionals as key differentiators that keep vehicles on the road longer and stronger.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Mechanical remanufacturing", "Electronic remanufacturing", "ABS module remanufacturing", "Electronic power steering module remanufacturing", "Transmission control module remanufacturing", "Instrument cluster remanufacturing", "Engine control module remanufacturing", "Body control module remanufacturing", "Hybrid electronic system remanufacturing", "Electronic EGR valve remanufacturing", "Mass air controller remanufacturing", "Electronic steering remanufacturing", "Electronic braking system remanufacturing", "Automotive replacement parts manufacturing", "Technical fluids formulation", "Gasket and head bolt manufacturing", "Steering component manufacturing"], "industries": ["Automotive aftermarket", "Automotive service and repair", "Professional automotive repair", "Warehouse distribution"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Veteran-owned family business spanning three generations", "ISO 9001:2015 certified quality management", "Extensive mechanical and electronic remanufacturing capabilities (ABS, EPS, TCM, ECU, hybrid systems)", "Direct connection with professional repair technicians for product development", "Online catalog integrated with major e-catalog platforms (Activant/Epicor, WHI)"], "facts_used": ["Founded in 1954 -> /about", "Headquartered in Cranbury, New Jersey -> /about", "Veteran-owned family business spanning three generations -> /about", "Privately owned with facilities in South Carolina, Michigan, Puebla, Mexico -> /about", "ISO 9001:2015 certified with TUV Rheinland -> /about", "Brands: AAE, Rein, Pentosin, AJUSA -> /about", "Mechanical and electronic remanufacturing capabilities -> /about", "List of remanufactured components (ABS, EPS, TCM, etc.) -> /about", "Online catalog powered by ShowMeTheParts.com -> /", "Celebrating 70 years of innovation -> /", "Purpose: build sustainable community; Vision: service market partner -> /about", "Close connection with professional repair technicians -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Our brands represent some of the finest products in their respective categories, including AAE steering components, Rein Automotive parts, Pentosin technical fluids, and AJUSA gaskets and head bolts.", "founded_year": "1954", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Veteran-owned", "Family-owned"]}'::jsonb, updated_at=now() WHERE slug='crp-automotive' AND approved AND profile IS NULL;
UPDATE companies SET description='CRS Hoods LLC operates from Smyrna, Delaware, tracing its roots to 1980 when Ron Grantland founded AG&G Sheet Metal, Inc. The family-owned business passed to his sons, Geoff and Andy, who worked alongside their father for decades.

The company designs, fabricates, and installs complete commercial kitchen ventilation systems. Its services cover Type I and Type II hood installation, exhaust fan installation and emergency repair, make-up air unit installation and balancing, welded grease duct fabrication, fire suppression integration, and ongoing repair, cleaning, and preventive maintenance. CRS Hoods serves Pennsylvania, New Jersey, Delaware, and Maryland, with more than 10,000 systems installed since 1980. The team includes a CEO, vice president, and senior supervisor, supported by field technicians who schedule work around kitchen operations, including nights and early mornings.

Customers range from independent restaurants and fast-food chains to cafes, bakeries, bars, hotels, schools, hospitals, food trucks, ghost kitchens, and institutional cafeterias. The company also works on food hall projects and other multi-venue operations.

CRS Hoods emphasizes a "first-time pass" inspection record, built on three pillars: maintaining proper clearance from combustibles per NFPA 96, calculating make-up air to balance building pressure, and ensuring airstream integrity through liquid-tight external welds. It holds professional licenses in all four states it serves and promotes end-to-end service from on-site assessment and CAD-backed design through final inspection walkthrough.', certifications=ARRAY['NFPA 96','International Mechanical Code (IMC)']::text[], profile='{"capabilities": ["Type I Hood Installation", "Type II Hood Installation", "Exhaust Fan Installation & Emergency Repair", "Make-Up Air Unit Installation & Balancing", "Welded Grease Duct Fabrication", "Commercial Ductwork Installation", "Fire Suppression System Integration", "Inspection Coordination", "Commercial Hood Repair", "Commercial Hood Cleaning", "Preventive Maintenance", "On-Site Assessment", "Facility Audit & Quote", "Custom Solutions", "CAD-Backed Design", "Professional Installation", "Final Inspection Walkthrough", "Code Compliance Consulting"], "industries": ["Restaurants", "Fast Food Chains", "Cafes & Bakeries", "Bars & Pubs", "Hotels", "Schools & Universities", "Hospitals", "Food Trucks", "Ghost Kitchens", "Institutional Cafeterias", "Food Halls"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Licensed in Pennsylvania, New Jersey, Delaware, and Maryland", "45+ years of industry experience (since 1980)", "10,000+ commercial kitchen exhaust systems installed", "End-to-end service from design to final sign-off", "First-time pass inspection focus: proper clearance, calculated make-up air, liquid-tight external welds"], "facts_used": ["Founded 1980 as AG&G Sheet Metal by Ron Grantland -> /about-us", "CRS Hoods LLC started July 2022 by Geoff and Andy -> /about-us", "10,000+ systems installed across PA, NJ, DE, MD -> /", "Licensed in PA, NJ, DE, MD -> /", "Services: Type I/II hood installation, exhaust fan, MUA, duct fabrication, fire suppression, repair, cleaning, maintenance -> /services", "Industries served: restaurants, fast food, cafes, bars, hotels, schools, hospitals, food trucks, ghost kitchens, institutional cafeterias, food halls -> /services", "Family-owned (local, family-run business) -> / (testimonial)", "NFPA 96 and IMC compliance -> /", "First-time pass inspection focus: proper clearance, calculated MUA, airstream integrity -> /", "Team: Samantha CEO, Andy VP, Jason Senior Supervisor -> /about-us", "Headquarters Smyrna, DE -> db", "Website: crshoods.com -> db"], "company_type": "Installer / service company", "makes_products": "yes", "type_evidence": "We''ve installed 10,000+ commercial kitchen exhaust systems across Pennsylvania, New Jersey, Delaware, and Maryland", "founded_year": "1980", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='crs-hoods-llc-restaurant-hood-installation' AND approved AND profile IS NULL;
UPDATE companies SET description='CTI Foods, headquartered in Saginaw, Texas, was founded in 1986 as a small business and has grown into an innovation-focused manufacturing and culinary company with six processing facilities strategically positioned across the United States.

The company specializes in custom food manufacturing, offering flash freezing, specialty packaging, and scale-to-volume production capabilities. Its six facilities provide supply chain redundancy for clients, supported by a team of classically trained chefs and food scientists who collaborate on product development from ideation to commercialization, including sensory science, line automation, and culinary supervision in every plant.

CTI Foods serves the food service industry, including global restaurant chains, distributors, food manufacturers, ingredient customers, and retailers. The company partners with clients to develop custom food products, menu concepts, and gold-standard flavor delivery systems that set brands apart.

The company differentiates itself through a rare combination of culinary expertise, technical innovation, and a commitment to the Global Food Safety Initiative, emphasizing small-kitchen craftsmanship at national scale and an entrepreneurial spirit that drives strategic partnerships with the largest North American customers.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom food manufacturing", "Flash freezing", "Specialty packaging", "Culinary R&D and product development", "Sensory science", "Scale-to-volume production", "Product commercialization", "Line automation and optimization", "Culinary supervision in production", "Product optimization"], "industries": ["Food service", "Restaurant chains", "Food distributors", "Food manufacturers", "Ingredient suppliers", "Retailers"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Six U.S. processing facilities for supply chain redundancy", "Commitment to Global Food Safety Initiative benchmarks", "Classically trained culinary and R&D team acting as client extension", "Flash freezing and specialty packaging capabilities", "Local supplier partnerships for fast turnaround"], "facts_used": ["Founded 1986 -> db, /about-us", "Headquarters Saginaw, Texas -> db", "Six processing facilities across U.S. -> /about-us, /", "Custom food manufacturing, flash freezing, specialty packaging -> db capabilities, /about-us", "Serves global restaurant chains, distributors, manufacturers, ingredient customers, retailers -> /", "Commitment to Global Food Safety Initiative -> /, /about-us", "Classically trained culinary and R&D team -> /about-us", "Entrepreneurial spirit drives strategic partnerships -> /about-us", "Small-kitchen craftsmanship at national scale -> /about-us", "Culinary supervision in every production facility -> /about-us", "Line automation and optimization -> /about-us", "Sensory science expertise -> /"], "company_type": "Manufacturer", "makes_products": "yes"