UPDATE companies SET description='Calsak Plastics, headquartered in Irving, Texas, was founded in 1972. The company began as a regional plastic sheet supplier and expanded into a nationwide distributor with seven branch locations across the United States.

The company distributes a broad range of plastic materials — including acrylic, polycarbonate, HDPE, PVC, PETG, ABS, engineering thermoplastics such as acetal, nylon, UHMW-PE, and PEEK, composite panels, and marine-grade plastics — in sheet, rod, and tube forms. It holds exclusive U.S. distribution rights for Acrycast® cell-cast acrylic and offers proprietary lines such as PolyGuard® polycarbonate, Trident® marine plastics, LumaTek® PVC boards, and Aluplast® aluminum composite panels. Value-added services include CNC routing, CNC drilling, thermoforming, cold and heat bending, polished edge finishing, assembly, kitting, and cut-to-size cutting with a standard tolerance of ±0.030″. Fabrication is performed in-house at each branch, enabling most cut-to-size orders to ship within one to three business days. The company also operates a closed-loop recycling program at all locations.

Calsak serves engineers, fabricators, procurement teams, and manufacturers across industries such as marine and boat building, architectural signage, construction, printing and graphics, aerospace, automotive, medical, retail display, data center, and advertising and art. Its materials are used for hulls, cabinetry, dock equipment, signage, cladding, glazing, printable substrates, data center containment panels, and medical device housings.

The company differentiates itself by combining global sourcing with domestic fulfillment, routing orders from the nearest branch to minimize lead times. Technical sales specialists provide material selection, compliance review, and specification guidance. Proprietary brands are developed for specific performance demands rather than repackaged commodity grades.', certifications=ARRAY[]::text[], profile='{"capabilities": ["CNC plastic routing", "CNC drilling", "Thermoforming", "Cold bending", "Heat bending", "Polished edge finishing", "Assembly and kitting", "Cut-to-size cutting", "Closed-loop recycling", "Material selection support", "Technical sales support", "Nationwide fulfillment", "Plastic sheet, rod, and tube distribution", "Proprietary brand development"], "industries": ["Marine and boat building", "Architectural signage", "Construction", "Printing and graphics", "Aerospace", "Automotive", "Medical", "Retail display", "Data center", "Advertising and art", "Manufacturing"], "materials": ["Acrylic (cell-cast and continuous-cast)", "Polycarbonate (UV-stabilized)", "HDPE", "PVC (rigid and foam)", "PETG", "ABS", "Acetal", "Nylon", "UHMW-PE", "PEEK", "Aluminum composite panels (Aluplast)", "Marine-grade E-ABS", "Expanded PVC (Trident)", "Acrycast PMMA", "PolyGuard polycarbonate", "LumaTek PVC boards", "AcryCycle recycled acrylic", "Acryglas", "LumaPrint substrates"], "equipment": [], "volume": "Single prototypes to full production runs", "lead_time": "1\u20133 business days for cut-to-size orders", "tolerances": "\u00b10.030\u2033 standard tolerance for cut-to-size", "built_on": ["Exclusive U.S. distributor of Acrycast\u00ae cell-cast acrylic", "In-house fabrication at all seven branch locations (CNC routing, drilling, thermoforming, bending, polishing, assembly, kitting)", "Cut-to-size service with \u00b10.030\u2033 tolerance, most orders shipping in 1\u20133 business days", "Closed-loop recycling program at every branch", "Global sourcing network with domestic fulfillment from the nearest branch"], "facts_used": ["Founded 1972 -> /about", "Headquarters Irving, Texas -> /about", "7 U.S. branch locations -> /about", "Exclusive U.S. distributor of Acrycast\u00ae cell-cast acrylic -> /about", "Proprietary brands: PolyGuard\u00ae, Trident\u00ae, LumaTek\u00ae, Aluplast\u00ae -> /about", "Materials: acrylic, polycarbonate, HDPE, PVC, PETG, ABS, engineering plastics, composite panels, marine-grade -> /about", "Fabrication services: CNC routing, CNC drilling, thermoforming, cold/heat bending, polished edge finishing, assembly, kitting, cut-to-size -> /services", "Cut-to-size tolerance \u00b10.030\u2033, most orders ship 1\u20133 business days -> /about", "Closed-loop recycling program at all branches -> /about", "Global sourcing with domestic fulfillment from nearest branch -> /about", "Industries served: marine, signage, construction, printing, aerospace, automotive, medical, retail display, data center, advertising & art -> /about, /services", "Technical sales support for material selection, compliance, specification -> /about", "Single prototypes to full production runs -> /services"], "company_type": "Distributor / reseller", "makes_products": "yes", "type_evidence": "Calsak Plastics is a U.S. plastic distributor founded in 1972, supplying plastic sheets, rods, and tubes through multiple branch locations nationwide.", "founded_year": "1972", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='calsak-plastics' AND approved AND profile IS NULL;
UPDATE companies SET description='CAM International, LLC is based in Smyrna, Tennessee. The company was founded in 1973 by James C. Van Slyke, who had worked in the automotive aftermarket since 1936. Recognizing a need for a more organized approach to handling stock lifts, changeovers, buybacks, and overstock inventories, Van Slyke established CAM International to reduce costs and disruption for manufacturers while providing accountability and equitable recovery. The business remains family-owned and operated, now led by third-generation president Matt Van Slyke.

CAM International operates as a redistributor and liquidator of genuine automotive aftermarket parts. The company purchases surplus inventory — including overruns, overstock, shelf-pulls, and packaging changes — from major manufacturers, warehouse distributors, and jobbers. Every piece is inspected, scanned, and packed at its facility, backed by a 30-day guarantee that parts are genuine (not reboxed or relabeled), currently cataloged, and in clean, salable condition. CAM describes itself as the oldest and largest aftermarket parts liquidator in the United States and Canada, with inventories spanning hundreds of brands and thousands of product lines.

The company serves automotive aftermarket manufacturers, warehouse distributors, and jobbers. Manufacturers use CAM’s stock-lift and changeover programs to minimize displacement expense and maximize recovery on competitive inventory. Distributors and jobbers turn to CAM to liquidate single product lines or entire operations, and to purchase discounted inventory at 20–70% off normal cost. CAM also handles heavy-duty parts stock lifts.

CAM International was started to bring accountability and equitable recovery to the stock-lift process, enabling warehouse distributors and jobbers to be more profitable and competitive. Its differentiators include a family-owned, third-generation leadership structure, a 3-way 30-day guarantee on every purchase, and specialization in manufacturer stock-lift and changeover programs.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Auto parts liquidation management", "Stock lift and changeover program management", "Surplus inventory purchasing (overruns, overstock, shelf-pulls, packaging changes)", "Inventory inspection, scanning, and packing", "30-day guarantee on genuine, cataloged, salable parts", "Warehouse distributor and jobber inventory liquidation", "Heavy-duty parts stock lift services", "End-to-end auto parts liquidation management"], "industries": ["Automotive aftermarket", "Auto parts and accessories", "Heavy duty parts"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Oldest and largest aftermarket parts liquidator in the United States and Canada", "3-way 30-day guarantee: genuine, currently cataloged, good condition", "Family-owned and operated since 1973 with third-generation leadership", "Specialists in manufacturer stock-lift and changeover programs", "In-house inspection, scanning, and packing of every piece"], "facts_used": ["Founded in 1973 by James C. Van Slyke -> /about-us", "Family-owned and operated since 1973 -> /", "Headquartered in Smyrna, Tennessee -> db", "Oldest and largest aftermarket parts liquidator in US and Canada -> /about-us", "3-way 30-day guarantee on genuine, cataloged, salable parts -> /", "Specialists in stock-lift/changeover programs for manufacturers -> /", "Inspects, scans, and packs every piece in-house -> /", "Serves automotive aftermarket manufacturers, warehouse distributors, jobbers -> /about-us", "Sells discounted inventory at 20-70% off normal cost -> /", "Handles heavy-duty parts stock lifts -> /", "President Matt Van Slyke is third-generation owner -> /about-us", "Team includes VP of Sales and Purchasing, EVP of Asset Recovery Services, National Sales Manager, Regional Sales Representatives -> /about-us"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "America''s Largest Auto Parts Redistributor", "founded_year": "1973", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='cam-international-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Carolina CoPacking operates from Henderson, North Carolina, where it was founded in 2018. It began as a full-service co-packer focused on sauces, dressings, and rubs, building a customer base through quality and flexibility.

The facility handles contract manufacturing, private label, and food service production, offering end-to-end services from product development and reformulation to cooking, bottling, packing, and shipping. The company notes it has expanded capacity recently and continually adopts new technology to increase efficiency. Its team comprises seasoned food-industry professionals who manage production and provide marketing support, packaging, and logistics.

Carolina CoPacking serves a range of clients from startup brands to large food-service groups and established retailers. It works with hundreds of brands across the sauce, dressing, and rub categories, helping them bring products to retail shelves and food-service channels. The company also assists with market insights and data analytics to help clients plan and scale.

The company emphasizes customer-focused production terms, fair and ethical partnerships, and leadership in food science and certification procedures. It differentiates itself by helping brands market to retailers, buyers, and consumers, using technology to track trends and maintain transparent communication. Reformulation services and supply-chain mitigation are also highlighted as key value drivers.', certifications=ARRAY['Acid and Acidified Foods Manufacturer']::text[], profile='{"capabilities": ["Contract manufacturing", "Private label production", "Food service production", "Product development", "Reformulation services", "Marketing support", "Packaging", "Shipping and logistics", "Market insights and data analytics", "Cooking, bottling, and packing", "Quality assurance", "Supply chain management"], "industries": ["Food & Beverage", "Food Service", "Retail", "Private Label", "Sauces", "Dressings", "Rubs"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Customer-focused production terms", "Fair and ethical business partnerships", "Leadership in food science, education, certification, and procedures", "Ability to help market brands to retailers, buyers, and end consumers", "Reformulation services from minor tweaks to major overhauls"], "facts_used": ["Founded in 2018 -> /about-us", "Located in Henderson, North Carolina -> /about-us", "Full-service co-packer of sauces, dressings, and rubs -> /about-us", "Family-driven culture -> /about-us", "Acid and Acidified Foods Manufacturer -> /about-us", "Contract manufacturing, private label, food services -> /", "Expanded capacity recently -> /", "Seasoned professionals in food industry and manufacturing -> /", "Reformulation services -> /about-us", "Marketing support for brands -> /about-us", "Market insights and data analytics -> /about-us", "Customer-focused production terms -> /about-us", "Fair and ethical business partnerships -> /about-us", "Leadership in food science,