UPDATE companies SET description='Carolina Electronic Assemblers, Inc. (CEA) operates from a 50,000-square-foot facility in Smithfield, North Carolina. The company has served contract manufacturing needs for more than 16 years, though a founding year is not publicly disclosed.

CEA develops and manufactures printed circuit board assemblies, cable and harness assemblies, and complete box builds. Its capabilities span surface-mount and through-hole PCB assembly, automated cable processing (350 MCM to 28 AWG), conformal coating, potting, functional testing, programming, and design documentation. The plant runs three SMT lines with Panasonic chip shooters and fine-pitch placement, BTU 10-zone ovens, two CR Technology AOI machines, an X-ray unit, universal insertion equipment, two wave solder machines (one RoHS-compliant using SAC305 alloy), a BGA rework station, and Cirris cable testers. The floor includes 22 manual solder cells separated for RoHS and non-RoHS work, four slide lines, and three final QC stations. Production volumes range from prototype to high-volume runs.

CEA states its mission is to be an industry leader in electronics manufacturing by continuously improving people, processes, and management to exceed customer expectations. It emphasizes quick turnaround, competitive pricing, and the flexibility of turnkey solutions, including reverse-engineering cable assemblies when drawings or bills of materials are unavailable.', certifications=ARRAY['IPC/WHMA-A-620']::text[], profile='{"capabilities": ["Turnkey manufacturing", "Surface mount PCB assembly", "Through-hole PCB assembly", "Cable/harness assembly", "Box build", "Conformal coating", "Potting", "Labels, overlays, front panels", "Full functional testing", "Programming", "Mechanical design documentation", "Radial auto-insertion", "Axial auto-insertion", "BGA placement", "SMT tape and reel", "Through-hole sequencing", "Material management", "Manufacturing documentation", "SMT and through-hole board repair", "PCB inspection (AOI)", "PCB inspection (X-ray)", "Wave solder (RoHS and non-RoHS)", "Cable testing (Cirris)", "Reverse engineering (cable/harness)", "Prototyping to production"], "industries": [], "materials": ["SAC 305 solder alloy", "Wire (350 MCM to 28 AWG)"], "equipment": ["Panasonic Chip Shooters", "Panasonic Fine Pitch Placement", "BTU 10 zone ovens", "Panapro software", "CR Technology AOI machines (two)", "CR Technology X-Ray unit", "Universal axial, radial and dip inserter", "Universal sequencer", "Automated cable/harness equipment (Tyco, Molex, T&B, Panduit)", "Cirris Systems testers (Cirris Easy-Wire)", "BGA rework station", "Electrovert wave solder machine", "Teamco wave solder machine", "4 slide lines", "22 manual solder work cells", "3 final QC inspection stations"], "volume": "Prototype to high volume production", "lead_time": "", "tolerances": "", "built_on": ["Full turnkey solutions from prototype through high-volume production", "Three SMT lines with Panasonic equipment and Panapro software for rapid changeover", "Separate RoHS and non-RoHS work cells and wave solder machines", "In-house automated cable/harness assembly with Cirris testing to IPC/WHMA-A-620", "BGA rework and X-ray inspection for complex assemblies"], "facts_used": ["Location: Smithfield, North Carolina -> db", "Facility: 50,000 sq ft climate-controlled building on 5 acres -> /capabilities", "3 SMT lines with Panasonic chip shooters, fine pitch placement, BTU 10 zone ovens -> /capabilities", "2 CR Technology AOI machines and CR Technology X-Ray unit -> /capabilities", "Universal axial/radial/dip inserter and sequencer -> /capabilities", "Automated cable/harness equipment for Tyco, Molex, T&B, Panduit -> /capabilities", "Wire processing 350MCM to 28awg -> /capabilities", "IPC/WHMA-A-620 standards for cable assembly -> /capabilities", "Cirris Systems testers for cable testing -> /capabilities", "BGA rework station -> /capabilities", "Two wave solder machines: Electrovert (non-ROHS) and Teamco (ROHS) with SAC305 alloy -> /capabilities", "4 slide lines, 22 manual solder work cells separated ROHS/non-ROHS -> /capabilities", "3 final QC inspection stations -> /capabilities", "Services: turnkey, PCB assembly, cable assembly, box build, conformal coating, potting, testing, programming, design documentation, repair -> /services", "Mission: industry leader in electronics manufacturing, exceed customer expectations -> /about", "More than 16 years of service -> /", "ROHS compliance -> db", "Prototype to high volume production -> /about"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "CEA specializes in the development and manufacturing of printed circuit board assemblies, cable assemblies and related electronic products.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='carolina-electronic-assemblers-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Carolina Wood Products operates from Marshville, North Carolina, where it has manufactured wood pallets and packaging since 1969. The company was founded by Robert and Frances Horne in nearby Peachland before moving to its current Marshville facility. Now in its third generation of family ownership, the business is led by Ronald and Randy Horne, with the next generation, Matt and Randall Horne, recently completing a major sawmill expansion.

The company produces new pallets to GMA standard and custom dimensions, heat-treated pallets certified to ISPM-15 for export, repaired and reconditioned pallets in Grade A and Grade B, as well as custom wooden crates and boxes built to exact specifications. Production relies on automated nailing machines and computerized saws, and a $2.5 million sawmill expansion completed recently added capacity for lumber processing and wood byproducts such as boiler fuel and wood chips. The Marshville facility serves customers across North Carolina, South Carolina, and Georgia.

Customers span manufacturing, food and agriculture, building materials and lumber, distribution and warehousing, export and international shipping, and biomass energy sectors. The company supplies pallets and packaging to businesses in Charlotte, Raleigh, Greensboro, Winston-Salem, Fayetteville, Durham, and throughout the Piedmont and coastal regions.

Carolina Wood Products emphasizes that it is a local manufacturer, not a broker, with every pallet built on-site in Marshville. This vertical integration allows consistent quality, faster turnaround, and direct communication with the production team. The family ownership and recent capital investment reflect a long-term commitment to the region’s supply chain.', certifications=ARRAY['ISPM-15']::text[], profile='{"capabilities": ["New pallet manufacturing (GMA standard and custom)", "Heat-treated pallets (ISPM-15 certified)", "Repaired/reconditioned pallets (Grade A and Grade B)", "Custom pallet manufacturing", "Custom wooden crate manufacturing", "Wooden box manufacturing", "Pallet recycling and recovery", "Lumber sawing and processing", "Wood byproduct production (boiler fuel, wood chips)", "Automated nailing", "Computerized sawing"], "industries": ["Manufacturing", "Food and Agriculture", "Building Materials and Lumber", "Distribution and Warehousing", "Export and International Shipping", "Biomass and Energy"], "materials": ["Wood", "Lumber", "Wood chips"], "equipment": ["Automated nailing machines", "Computerized saws", "Sawmill"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Manufactures on-site in Marshville, NC, not a broker", "ISPM-15 certified in-house heat treatment for export", "Custom pallet and crate sizing to exact specifications", "$2.5 million sawmill expansion for capacity and quality", "Third-generation family ownership since 1969"], "facts_used": ["Founded 1969 by Robert and Frances Horne -> /about", "Family-owned, third generation -> /about", "Headquarters in Marshville, NC -> /", "Manufactures new, heat-treated, repaired, custom pallets, crates, boxes -> /", "ISPM-15 certified heat treatment -> /", "Automated nailing machines and computerized saws -> /about", "$2.5 million sawmill expansion -> /about", "Industries served: Manufacturing, Food and Agriculture, Building Materials, Distribution, Export, Biomass -> /", "Service area: NC, SC, GA -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Carolina Wood Products of Marshville manufactures new pallets, heat-treated pallets, and custom wood packaging across North Carolina, South Carolina, and Georgia.", "founded_year": "1969", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["ISPM-15 certified heat treatment for export compliance"], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='carolina-wood-products' AND approved AND profile IS NULL;
UPDATE companies SET description='The company maintains its corporate offices in Plaistow, New Hampshire, while the Pepperell, Massachusetts location serves as one of 21 retail and commercial outlets spread across New Hampshire, Massachusetts, and Maine.

Each site carries inventory for immediate counter sale and runs commercial delivery routes for professional repair shops, with express and courier options advertised for urgent needs.

The company positions its longevity and service model as its differentiator, emphasizing that many staff members have spent four decades in the industry. Its internal motto, "SERVICE IS THE DIFFERENCE," reflects a strategy built on in-person counter expertise and rapid local delivery rather than catalog breadth alone.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Automotive parts distribution", "Counter sales", "Commercial delivery routes", "Express courier service", "Heavy-duty truck parts supply", "Inventory management for repair shops"], "industries": ["Automotive aftermarket", "Automotive repair", "Heavy-duty truck repair", "Fleet maintenance"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["21 locations across New Hampshire, Massachusetts, and Maine", "Express and courier delivery for commercial accounts", "45+ years of continuous operation since 1975", "Auto Value network affiliation for national buying power", "Locally owned with long-tenured staff"], "facts_used": ["Founded 1975 -> db", "21 locations across NH, MA, ME -> page /", "Corporate offices in Plaistow, NH -> page /", "Locally owned and operated -> db description", "Auto Value affiliation -> page /", "Motor Supply division with 8 Maine locations -> page /", "Steve''s Auto Parts division -> page /", "Express and courier services offered -> page /", "Staff with 40+ years industry experience -> db description", "Pepperell, MA location at 166 Main Street -> page /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "Carparts Distribution Center is a locally owned and operated automotive parts supplier", "founded_year": "1975", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='carparts-of-pepperell' AND approved AND profile IS NULL;
UPDATE companies SET description='Carpin Manufacturing, Inc. was founded in 1984 in Waterbury, Connecticut, by Ralph Carpinella, an engineer who applied his manufacturing expertise to create a glide and hardware company serving the office and school furniture markets.

The company operates a modern facility near Interstate 84 where it runs progressive and eyelet metal stamping, plastic injection molding, and precision assembly lines. In-house engineering, rapid prototyping, and 3D printing support custom development alongside a catalog of nearly 3,000 stock SKUs, many available for same-day shipment. A stable workforce with an average tenure of 20 years underpins consistent quality and process knowledge.

Carpin supplies floor‑protection products — glides, casters, tubular components, and specialty parts — to schools and universities, commercial and residential office furniture makers, warehouse and factory equipment builders, point‑of‑sale display manufacturers, and medical‑device firms. Notable collaborations include redesigning a side‑chair glide to eliminate field failures for a major office furniture brand and co‑developing a custom caster that matched a task chair’s aesthetic requirements.

The firm emphasizes engineering‑driven problem solving over off‑the‑shelf sales, a philosophy rooted in its founding. Patented glide designs such as the Solo, Smart, Floor Saver, and Simple lines illustrate its focus on proprietary solutions, and the company has been recognized with the James C. Smith Spirit of Excellence Award for its contributions to the industry.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Injection molding", "Progressive metal stamping", "Eyelet metal stamping", "Precision assembly", "In-house engineering design", "Rapid prototyping", "3D printing", "Custom product development"], "industries": ["Schools and universities", "Office furniture (commercial and residential)", "Warehouse and factory equipment", "Point-of-sale displays", "Medical applications"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Nearly 3,000 stock SKUs with same-day shipping on many items", "In-house engineering design, rapid prototyping, and 3D printing for custom solutions", "Workforce averaging 20 years of tenure", "Patented glide and caster designs (Solo, Smart, Floor Saver, Simple)", "Customer-specific problem solving beyond standard catalog offerings"], "facts_used": ["Founded 1984 by Ralph Carpinella (engineer) -> /about", "Henry Carpinella (father) integral to startup until 2011 -> /about", "Headquarters Waterbury, Connecticut near I-84 -> /about", "Facility with progressive/eyelet metal stamping, injection molding, precision assembly -> /about", "In-house engineering design, rapid prototyping, 3D printing -> /about", "Nearly 3,000 SKUs, many same-day shipping -> /about", "Workforce average tenure 20 years -> /about", "Industries: schools/universities, office furniture, warehouse/factory equipment, point-of-sale displays, medical -> /about", "Patented glide lines: Solo, Smart, Floor Saver, Simple -> /", "Testimonial: side-chair glide redesign for major office furniture manufacturer -> /", "Testimonial: custom caster co-development for task chair aesthetic -> /", "James C. Smith Spirit of Excellence Award 2026 -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Carpin Manufacturing is the leading manufacturer and importer of metal stamped and plastic injection molded floor protection products.", "founded_year": "1984", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='carpin-manufacturing-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Cavist was incorporated in Reno, Nevada, in 1998 by Danish-born founders Kurt Carlson and Reimer Hansen to bring European low-pressure molding technology to the United States. The company began as an equipment developer, introducing the MoldMan line of low-pressure molding machines, before launching a contract manufacturing division in 2008. In 2023, after 26 years of growth, Cavist transitioned to 100% employee ownership.

Today Cavist operates as a contract manufacturer specializing in encapsulating and protecting electronic assemblies. Its core processes include low-pressure molding (LPM), 2-shot overmolding, epoxy overmolding, and cable assembly overmolding, supplemented by turnkey supply services that cover procurement, assembly, testing, and packaging. The 30,000-square-foot facility houses more than 25 injection molding machines and a staff of 35-plus engineers, technicians, and support personnel. Quality systems are certified to ISO 9001:2015 and ISO 13485:2016, and the site includes ISO Class 8 cleanrooms for medical device work.

The company serves automotive, medical, wearable, and defense markets, with customers ranging from individual inventors to Fortune 500 corporations. Automotive programs include sealing for EV and under-hood electronics; medical projects cover implantable and wearable devices requiring biocompatible materials; defense work addresses ruggedized connectors and cable assemblies for harsh environments.

Cavist differentiates itself through 25-plus years of dedicated low-pressure molding experience, in-house moldflow simulation that validates gating and fill before production, and engineering support that begins at the design stage with DFM, material selection, and prototyping. The employee-owned structure is intended to ensure long-term stability and accountability from prototype through high-volume runs.', certifications=ARRAY['ISO 9001:2015','ISO 13485:2016']::text[], profile='{"capabilities": ["Low Pressure Molding (LPM)", "2-Shot Overmolding", "Epoxy Overmolding", "Cable Assembly Overmolding", "Turnkey Supply (procurement, assembly, testing, packaging)", "Design for Manufacturability (DFM)", "Industrial Design", "Material Selection", "Moldflow Simulation", "Prototyping", "High Volume Manufacturing", "First Article Inspection", "Process Validation", "PPAP (Production Part Approval Process)", "Cleanroom Manufacturing (ISO Class 8)"], "industries": ["Automotive", "Medical", "Wearables", "Defense", "Medical Devices & Electronics"], "materials": ["Epoxy Molding Compounds", "Engineering Thermoplastics", "Biocompatible Materials"], "equipment": ["Arburg injection molding machines", "MoldMan low-pressure molding machines (MoldMan 8000, MoldMan 8200)", "Keyence LM1100 vision measurement system", "Keyence VR6200 vision measurement system", "Mettler Toledo HX204 moisture analyzer", "DVNXLV rheometer", "Ohaus high-accuracy weight scale"], "volume": "Prototype to high volume", "lead_time": "", "tolerances": "", "built_on": ["25+ years of low-pressure molding experience since 1998", "In-house moldflow simulation before any part is molded", "Engineering support from day one (DFM, material selection, prototyping)", "Vision-to-volume scaling from single prototype to high-volume production", "100% employee-owned since 2023"], "facts_used": ["Founded 1998 by Kurt Carlson and Reimer Hansen -> /about-us", "Headquarters Reno, Nevada -> /about-us", "Employee-owned since 2023 -> /about-us", "35+ employees, 25+ injection molding machines, 30,000 sq ft facility -> /about-us", "ISO 9001:2015 and ISO 13485:2016 certified -> /about-us, /quality", "Processes: Low Pressure Molding, 2-Shot Overmolding, Epoxy Overmolding, Cable Assembly Overmolding, Turnkey Supply -> /services", "Industries: Automotive, Medical, Wearables, Defense -> /, /services", "Equipment: Arburg injection molding machines, MoldMan machines, Keyence vision systems, Mettler Toledo moisture analyzer, DVNXLV rheometer, Ohaus scale -> /services, /quality", "Materials: Epoxy Molding Compounds, engineering thermoplastics, biocompatible options -> /services", "Volume range: prototype to high volume -> /services", "In-house moldflow simulation -> /services", "Engineering support from day one (DFM, material selection, prototyping) -> /services", "ISO Class 8 cleanrooms per ISO 14644-1 -> /quality"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Cavist is a contract manufacturer specializing in sealing and protecting electronics via low pressure injection molding technology", "founded_year": "1998", "employee_count": "35+", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Employee-owned"]}'::jsonb, updated_at=now() WHERE slug='cavist' AND approved AND profile IS NULL;
UPDATE companies SET description='CCX Corporation operates from Broomfield, Colorado, drawing on over three decades of cable design and manufacturing experience. The company positions itself as a North American manufacturer of custom and high-speed cables and connectivity solutions, producing custom cables to customer specifications alongside high-speed fiber, copper, power cables, and a full suite of optics. No founding year or founder names are publicly disclosed, and ownership structure is not specified.

The company''s capabilities span simple and complex wire harnesses with dozens to hundreds of components, coaxial cable assemblies for 50- and 75-ohm applications including low-loss variants, ribbon assemblies in flat, folded, and color-coded configurations, and custom injection over-molding for strain relief and interconnects. CCX also terminates motor and fan leads, manufactures power cords and adapters certified to UL, cUL, ENEC, VDE, CE, and CCC standards, and builds fiber patch cables (1–144 fibers, OS2/OM1–OM5) in a Class 10k clean room. Copper offerings cover CAT5e through CAT8 in shielded and unshielded versions, plus SAS 3.0 12 Gbps assemblies. The product line extends to compatible optics (SFPs), direct-attach and active optical cables with stateside stocking, and data-center rack integration services.

CCX serves original equipment manufacturers, resellers, and data-center operators. Its customer base includes companies such as Arrow, referenced in a testimonial, and the firm highlights rack-and-stack integration projects for data-center clients. The company markets directly to both OEMs and channel partners through its website.

CCX emphasizes quality-first manufacturing, on-time delivery, and what it describes as unparalleled customer service backed by a friendly, educated team. Differentiators cited include a Class 10k clean room for fiber production, lifetime warranty on optics, TAA-compliant options across power, fiber, and copper lines, and domestic stocking for quick-turn DAC and AOC orders.', certifications=ARRAY['RoHS','UL','cUL','ENEC','VDE','CE','CCC','REACH']::text[], profile='{"capabilities": ["Custom cable design and manufacturing", "Wire harness assembly (simple to complex multi-branch)", "Coaxial cable assemblies (50/75 Ohm, low-loss)", "Ribbon cable assemblies (flat, folded, color-coded)", "Custom injection over-molding", "Motor and fan lead termination and connectorization", "Power cable and adapter manufacturing (UL, cUL, ENEC, VDE, CE, CCC certified)", "Fiber patch cable manufacturing (1\u2013144 fibers, OS2/OM1\u2013OM5)", "Copper patch cable manufacturing (CAT5e\u2013CAT8, shielded/unshielded)", "SAS 3.0 12 Gbps cable assemblies", "Optics/SFP programming and compatibility testing", "Direct-attach copper (DAC) and active optical cable (AOC) assembly", "Data center rack integration and stack services", "Custom assembly quoting, engineering, quality control, and testing"], "industries": ["Original equipment manufacturers (OEMs)", "Resellers / channel partners", "Data centers"], "materials": ["Multi-stranded copper (24 AWG to 00 AWG)", "Singlemode fiber (OS2)", "Multimode fiber (OM1, OM2, OM3, OM4, OM5)", "Fiber connectors (LC, SC, MPO, MTP\u00ae)", "Fiber jacketing (PVC Riser, Plenum, LSZH, Armored)", "Coaxial cable (RG58, RG59, RG174, 195, Low Loss 240, Low Loss 400)", "Copper patch cable (CAT5e, CAT6, CAT6a, CAT7, CAT8; AWG 23, 24, 26, 28)", "SAS cable (SAS 3.0 12 Gbps, SFF-8644 HD Mini-SAS)", "Power connectors (NEMA, Twist Lock, P-Lock)", "Various wire jacketing materials"], "equipment": ["Class 10k clean room"], "volume": "", "lead_time": "", "tolerances": "", "built_o